-- Run once in MySQL Workbench (safe to re-run). Matches Assignments 4-6.
CREATE DATABASE IF NOT EXISTS petplusedb;
USE petplusedb;
CREATE TABLE IF NOT EXISTS Users (UserID INT AUTO_INCREMENT PRIMARY KEY, Name VARCHAR(100) NOT NULL, Email VARCHAR(100), Phone VARCHAR(15), Password VARCHAR(255) NOT NULL);
ALTER TABLE Users MODIFY Password VARCHAR(255) NOT NULL;  -- room for hashed passwords
CREATE TABLE IF NOT EXISTS Veterinarians (Vet_ID INT AUTO_INCREMENT PRIMARY KEY, Vet_Name VARCHAR(100) NOT NULL, Specialization VARCHAR(50), Phone VARCHAR(15), Street VARCHAR(100), City VARCHAR(50), Pincode VARCHAR(10));
CREATE TABLE IF NOT EXISTS Pet (Pet_ID INT AUTO_INCREMENT PRIMARY KEY, User_ID INT, Pet_Name VARCHAR(50) NOT NULL, Species VARCHAR(30), Breed VARCHAR(50), Gender VARCHAR(10), DOB DATE, FOREIGN KEY (User_ID) REFERENCES Users(UserID));
CREATE TABLE IF NOT EXISTS MilkYieldLog (Log_ID INT AUTO_INCREMENT PRIMARY KEY, Pet_ID INT, Log_Date DATE, Morning_Yield DECIMAL(5,2), Evening_Yield DECIMAL(5,2), Total_Yield DECIMAL(6,2) GENERATED ALWAYS AS (Morning_Yield + Evening_Yield) STORED, FOREIGN KEY (Pet_ID) REFERENCES Pet(Pet_ID));
CREATE TABLE IF NOT EXISTS HealthRecords (Record_ID INT AUTO_INCREMENT PRIMARY KEY, Pet_ID INT, Vet_ID INT, Visit_Date DATE, Diagnosis VARCHAR(200), Prescription VARCHAR(200), FOREIGN KEY (Pet_ID) REFERENCES Pet(Pet_ID), FOREIGN KEY (Vet_ID) REFERENCES Veterinarians(Vet_ID));
CREATE TABLE IF NOT EXISTS Vaccinations (Vaccination_ID INT AUTO_INCREMENT PRIMARY KEY, Pet_ID INT, Vaccine_Name VARCHAR(100), Dose_Date DATE, Next_Due_Date DATE, FOREIGN KEY (Pet_ID) REFERENCES Pet(Pet_ID));